const agent=$input.first().json;
const response={status:'completed',model:'gpt-5.4-mini (configured)',output:[{type:'message',content:[{type:'output_text',text:agent.output}]}]};
const context=$('Read care context').first().json;
const job=$('Selected request').first().json;
if (response.status && response.status!=='completed') throw new Error('LLM response incomplete');
const content=(response.output||[]).filter(x=>x.type==='message').flatMap(x=>x.content||[]);
if (content.some(x=>x.type==='refusal')) throw new Error('LLM refused the request');
const blocks=content.filter(x=>x.type==='output_text');
if (blocks.length!==1) throw new Error('Expected one structured output block');
const out=typeof blocks[0].text==='string'?JSON.parse(blocks[0].text):blocks[0].text;
if (!out || typeof out!=='object' || Array.isArray(out)) throw new Error('Expected JSON object');
const keys=['action','rationale','message_body','call_script','missing_fields'];
if (Object.keys(out).some(k=>!keys.includes(k)) || keys.some(k=>!(k in out))) throw new Error('Unexpected output schema');
for (const field of ['action','rationale']) if (typeof out[field]!=='string'||!out[field].trim()||out[field].length>10000) throw new Error('Invalid '+field);
for (const field of ['message_body','call_script']) if (out[field]!==null&&(typeof out[field]!=='string'||!out[field].trim()||out[field].length>10000)) throw new Error('Invalid '+field);
if (!Array.isArray(out.missing_fields)||out.missing_fields.some(x=>typeof x!=='string'||x.length>500)||out.missing_fields.length>30) throw new Error('Invalid missing_fields');
const type=context.requested_output;
if (!['message','call_script','explanation','care_pack'].includes(type)) throw new Error('Unknown request type');
if (type==='explanation'&&(out.message_body!==null||out.call_script!==null)) throw new Error('Explanation must not produce outbound content');
if (type==='call_script'&&(!out.call_script||out.message_body!==null)) throw new Error('Call script must not produce a message');
if (['message','care_pack'].includes(type)&&!out.message_body) throw new Error('Message body required');
if (type==='message'&&out.call_script!==null) throw new Error('Unexpected call script');
return [{json:{p_job_id:job.id,p_action:out.action,p_rationale:out.rationale,p_message_body:out.message_body,p_call_script:out.call_script,p_missing_fields:out.missing_fields,p_generation_mode:'llm',p_model_version:response.model||'gpt-5.4-mini',p_prompt_version:'retention-agent-v3',p_offer_id:null},pairedItem:{item:0}}];
